/*
 * PROTOTYPE, throwaway. Shared blog engine for the E and F blog pages.
 *
 * Posts are static markdown files in posts/<slug>.md (optional posts/<slug>.pt.md).
 * posts/index.json is generated by build_posts.py (serve.py regenerates it on request).
 *
 * Requires (load before this file): content.js, marked (UMD), DOMPurify, highlight.js.
 *
 *   KUCH_BLOG.list()                 -> Promise<Entry[]>  newest first, localized for the UI language
 *   KUCH_BLOG.get(slug)              -> Promise<Post | null>
 *   KUCH_BLOG.enhance(rootEl)        -> highlights code, wires copy buttons and heading anchors
 *   KUCH_BLOG.t                      -> UI strings for the active language
 *   KUCH_BLOG.formatDate(iso)        -> "16 Feb 2024" / "16 fev 2024"
 *   KUCH_BLOG.postUrl(slug), .tagUrl(tag), .editUrl(slug), .feedUrl
 *
 * Entry: { slug, title, description, topic, cover, date, updated, tags, readingMinutes, langs, lang }
 * Post:  Entry + { html, toc: [{id, text, level}], words, translated, prev, next }
 */
(function () {
  const lang = (window.KUCH && window.KUCH.lang) || "en";
  const REPO = "https://github.com/mkuchak/blog";
  const POSTS_PATH = "site/posts";
  // KUCH_SITE is injected by site/build.py: { root: "/", pretty: true, ... }. Without it, paths stay relative.
  const SITE = window.KUCH_SITE || {};
  const ROOT = SITE.root || "";
  const BLOG_PAGE = (window.KUCH_VARIANT && window.KUCH_VARIANT.blogPage) || location.pathname.split("/").pop() || "blog-e.html";
  const postMeta = document.querySelector('meta[name="kuch-post"]');

  const T = {
    en: {
      blog: "Field notes",
      blogSub: "Long-form notes on AI agents, LLM systems and full-stack engineering.",
      allPosts: "All posts",
      back: "All posts",
      search: "Search posts",
      noResults: "No posts match that search.",
      tags: "Tags",
      all: "All",
      minRead: "min read",
      onThisPage: "On this page",
      share: "Share",
      copyLink: "Copy link",
      copied: "Copied",
      copy: "Copy",
      edit: "Edit on GitHub",
      prev: "Previous",
      next: "Next",
      published: "Published",
      updated: "Updated",
      onlyEnglish: "This article is only available in English for now.",
      notFound: "That post doesn't exist (yet).",
      offline: "Run the local server to load posts: pnpm prototype:landing",
      rss: "RSS",
      readPost: "Read",
      latest: "Latest",
      comingUp: "Coming up",
      words: "words",
      topic: "Topic",
      home: "Home",
    },
    pt: {
      blog: "Notas de campo",
      blogSub: "Textos longos sobre agentes de IA, sistemas com LLM e engenharia full-stack.",
      allPosts: "Todos os posts",
      back: "Todos os posts",
      search: "Buscar posts",
      noResults: "Nenhum post combina com essa busca.",
      tags: "Tags",
      all: "Todos",
      minRead: "min de leitura",
      onThisPage: "Nesta página",
      share: "Compartilhar",
      copyLink: "Copiar link",
      copied: "Copiado",
      copy: "Copiar",
      edit: "Editar no GitHub",
      prev: "Anterior",
      next: "Próximo",
      published: "Publicado",
      updated: "Atualizado",
      onlyEnglish: "Este artigo por enquanto só existe em inglês.",
      notFound: "Esse post não existe (ainda).",
      offline: "Rode o servidor local para carregar os posts: pnpm prototype:landing",
      rss: "RSS",
      readPost: "Ler",
      latest: "Mais recente",
      comingUp: "Em breve",
      words: "palavras",
      topic: "Tema",
      home: "Início",
    },
  }[lang];

  // ---------- Front matter (same subset as build_posts.py) ----------
  function parseFrontMatter(text) {
    text = text.replace(/\r\n/g, "\n");
    const m = text.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
    if (!m) return { meta: {}, body: text };
    const meta = {};
    for (const line of m[1].split("\n")) {
      const i = line.indexOf(":");
      if (i < 0 || line.trim().startsWith("#")) continue;
      const key = line.slice(0, i).trim();
      let raw = line.slice(i + 1).trim();
      if (raw.startsWith("[")) {
        try { meta[key] = JSON.parse(raw); } catch { meta[key] = raw.replace(/^\[|\]$/g, "").split(",").map((v) => v.trim().replace(/^['"]|['"]$/g, "")).filter(Boolean); }
      } else if (/^(['"]).*\1$/.test(raw)) meta[key] = raw.slice(1, -1);
      else if (raw === "true" || raw === "false") meta[key] = raw === "true";
      else meta[key] = raw.replace(/\s+#.*$/, "");
    }
    return { meta, body: m[2] };
  }

  // ---------- Index ----------
  let indexPromise = null;
  function list() {
    if (!indexPromise) {
      indexPromise = fetch(ROOT + "posts/index.json", { cache: "no-store" })
        .then((r) => (r.ok ? r.json() : Promise.reject(new Error(r.status))))
        .then((entries) => entries.map(localize));
    }
    return indexPromise;
  }

  function localize(e) {
    const tr = lang === "pt" && e.i18n && e.i18n.pt;
    // Translated metadata applies even without a translated body; the body is Portuguese only when it exists.
    const body = lang === "pt" && (e.langs || []).includes("pt") ? "pt" : "en";
    return Object.assign({}, e, tr || {}, { lang: body });
  }

  // ---------- Markdown ----------
  // GitHub-style heading ids (same as github-slugger): keeps letters, digits, "_" and "-", spaces become "-".
  const slugify = (s) => s.toLowerCase().replace(/[^\p{L}\p{N}\s_-]/gu, "").trim().replace(/\s/g, "-");
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  function render(md) {
    const toc = [];
    const used = {};
    const renderer = new marked.Renderer();
    renderer.heading = function (token) {
      const inner = this.parser.parseInline(token.tokens);
      const tmp = document.createElement("div");
      tmp.innerHTML = inner;
      const plain = tmp.textContent.trim();
      let id = slugify(plain) || "section";
      used[id] = (used[id] || 0) + 1;
      if (used[id] > 1) id += "-" + used[id];
      if (token.depth === 2 || token.depth === 3) toc.push({ id, text: plain, level: token.depth });
      return `<h${token.depth} id="${id}"><a class="anchor" href="#${id}" aria-hidden="true" tabindex="-1">#</a>${inner}</h${token.depth}>`;
    };
    renderer.code = function (token) {
      // Info strings can be a language ("ts") or a file name ("User.ts"); file names show as the label.
      const info = (token.lang || "").split(/\s/)[0];
      const isFile = /\.[a-z0-9]+$/i.test(info);
      const ext = isFile ? info.split(".").pop().toLowerCase() : info.toLowerCase();
      const lang = { ts: "typescript", tsx: "typescript", js: "javascript", mjs: "javascript", sh: "bash", zsh: "bash", yml: "yaml", md: "markdown" }[ext] || ext;
      const label = info || "text";
      return `<figure class="code${isFile ? " file" : ""}" data-lang="${esc(lang || "text")}"><figcaption><span>${esc(label)}</span><button type="button" class="copy" data-copy>${esc(T.copy)}</button></figcaption><pre><code class="${lang ? "language-" + esc(lang) : "nohighlight"}">${esc(token.text)}</code></pre></figure>`;
    };
    renderer.image = function (token) {
      const alt = token.text || "";
      return `<figure class="img"><img src="${esc(token.href)}" alt="${esc(alt)}" loading="lazy" decoding="async">${alt ? `<figcaption>${esc(alt)}</figcaption>` : ""}</figure>`;
    };
    renderer.link = function (token) {
      const text = this.parser.parseInline(token.tokens);
      const ext = /^https?:\/\//.test(token.href) && !token.href.startsWith(location.origin);
      return `<a href="${esc(token.href)}"${token.title ? ` title="${esc(token.title)}"` : ""}${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${text}</a>`;
    };
    renderer.table = function (token) {
      const html = marked.Renderer.prototype.table.call(this, token);
      return `<div class="table-wrap">${html}</div>`;
    };
    // <details> blocks written without blank lines (fine in MDX) need them for CommonMark to parse the inside.
    md = md.replace(/(<\/summary>)[ \t]*\n(?!\n)/g, "$1\n\n").replace(/([^\n])\n(<\/details>)/g, "$1\n\n$2");
    const raw = marked.parse(md, { gfm: true, breaks: false, renderer });
    const html = DOMPurify.sanitize(raw, { ADD_ATTR: ["target", "data-copy", "data-lang"], ADD_TAGS: ["figure", "figcaption"] });
    return { html, toc };
  }

  async function get(slug) {
    const entries = await list();
    const i = entries.findIndex((e) => e.slug === slug);
    if (i < 0) return null;
    const entry = entries[i];
    const file = ROOT + (entry.lang === "pt" ? `posts/${slug}.pt.md` : `posts/${slug}.md`);
    const res = await fetch(file, { cache: "no-store" });
    if (!res.ok) return null;
    const { body } = parseFrontMatter(await res.text());
    const { html, toc } = render(body);
    const words = (body.replace(/```[\s\S]*?```/g, " ").match(/\w+/g) || []).length;
    return Object.assign({}, entry, {
      html,
      toc,
      words,
      translated: lang === "pt" && entry.lang === "pt",
      untranslated: lang === "pt" && entry.lang !== "pt",
      prev: entries[i + 1] || null, // older
      next: entries[i - 1] || null, // newer
    });
  }

  // ---------- After render ----------
  function enhance(root) {
    if (window.hljs) root.querySelectorAll("pre code:not(.nohighlight)").forEach((el) => hljs.highlightElement(el));
    root.querySelectorAll("[data-copy]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const code = btn.closest("figure").querySelector("code").innerText;
        try { await navigator.clipboard.writeText(code); } catch {}
        btn.textContent = T.copied;
        btn.classList.add("ok");
        setTimeout(() => { btn.textContent = T.copy; btn.classList.remove("ok"); }, 1400);
      });
    });
    root.querySelectorAll("details").forEach((d) => d.classList.add("fold"));
  }

  const MONTHS = {
    en: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
    pt: ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"],
  }[lang];
  function formatDate(iso) {
    const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (!m) return iso || "";
    return `${+m[3]} ${MONTHS[+m[2] - 1]} ${m[1]}`;
  }

  // URL params, plus the post slug when this is a pre-rendered /blog/<slug>/ page.
  function query() {
    const q = new URLSearchParams(location.search);
    if (SITE.forcePost) q.set("post", SITE.forcePost); // 404.html renders the blog's not-found view
    const slug = postMeta && postMeta.content;
    if (slug && !q.get("post") && location.pathname.replace(/\/+$/, "").endsWith("/" + slug)) q.set("post", slug);
    return q;
  }

  window.KUCH_BLOG = {
    lang,
    t: T,
    list,
    get,
    enhance,
    formatDate,
    parseFrontMatter,
    slugify,
    postUrl: (slug) => (SITE.pretty ? `${BLOG_PAGE}${encodeURIComponent(slug)}/` : `${BLOG_PAGE}?post=${encodeURIComponent(slug)}`),
    tagUrl: (tag) => `${BLOG_PAGE}?tag=${encodeURIComponent(tag)}`,
    indexUrl: () => BLOG_PAGE,
    editUrl: (slug) => `${REPO}/blob/main/${POSTS_PATH}/${slug}.md`,
    feedUrl: ROOT + "feed.xml",
    params: query(),
    query,
    // Drafts announced as "coming up". build.py inlines them as window.KUCH_DRAFTS (localized).
    drafts: () => window.KUCH_DRAFTS || null,
  };
})();
